mapper.select:
select 

from activity_day_report
where id = #{id,jdbcType=BIGINT}

SELECT id,user_id,user_name,org_id,org_name,sales_date,SUM(completion_rate)as completion_rate,SUM(sale_amount) as sale_amount, sale_goal FROM activity_day_report
WHERE DATE_FORMAT(sales_date,'%Y-%m') = DATE_FORMAT(#{salesDate,jdbcType=DATE},'%Y-%m') GROUP BY user_id ORDER BY completion_rate desc
 limit #{pageIndex} , #{pageSize}

SELECT id,user_id,user_name,org_id,org_name,sales_date,sign_num  FROM activity_day_report
where  DATE_FORMAT(sales_date,'%Y-%m-%d') = DATE_FORMAT(NOW(),'%Y-%m-%d') ORDER BY sign_num desc
limit #{pageIndex} , #{pageSize}

SELECT id,user_id,user_name,org_id,org_name,sales_date,SUM(sign_num)as sign_num FROM activity_day_report
WHERE DATE_FORMAT(sales_date,'%Y-%m') = DATE_FORMAT(NOW(),'%Y-%m') GROUP BY user_id  ORDER BY sign_num desc
limit #{pageIndex} , #{pageSize}

SELECT id,user_id,user_name,org_id,org_name,sales_date,SUM(sign_num)as sign_num FROM activity_day_report
WHERE DATE_FORMAT(sales_date,'%Y-%m')=DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH),'%Y-%m')  GROUP BY user_id  ORDER BY sign_num desc
limit #{pageIndex} , #{pageSize}

SELECT id,user_id,user_name,org_id,org_name,sales_date,visit_num  FROM activity_day_report
where  DATE_FORMAT(sales_date,'%Y-%m-%d') = DATE_FORMAT(NOW(),'%Y-%m-%d') ORDER BY visit_num desc
limit #{pageIndex} , #{pageSize}

SELECT id,user_id,user_name,org_id,org_name,sales_date,SUM(visit_num)as visit_num FROM activity_day_report
WHERE DATE_FORMAT(sales_date,'%Y-%m') = DATE_FORMAT(NOW(),'%Y-%m') GROUP BY user_id  ORDER BY visit_num desc
limit #{pageIndex} , #{pageSize}
